import os, re, json, subprocess

APP = os.path.expanduser("~/proggs/BestJournalAndroid")
TARGET = os.path.join(APP, "app/src/main/res/values-bn/strings.xml")
CKPT = os.path.join(APP, ".android-shield/worker-checkpoints/tw-bn.jsonl")

def ck(stage, data):
    os.makedirs(os.path.dirname(CKPT), exist_ok=True)
    with open(CKPT, "a", encoding="utf-8", newline="\n") as f:
        f.write(json.dumps({"stage": stage, **data}, ensure_ascii=False) + "\n")

