# ---- Plurals (Bengali: one, other; Arabic numerals via %1$d) ----
PLURALS = {
 "datetime_months_relative": {"one": "%1$d মাস আগে", "other": "%1$d মাস আগে"},
 "datetime_years_relative":  {"one": "%1$d বছর আগে", "other": "%1$d বছর আগে"},
}

NEW_KEYS = ["paywall_monthly_note"]

def esc(s):
    # for regex replacement value: escape backreference-significant chars
    return s.replace('\\', '\\\\')

with open(TARGET, "r", encoding="utf-8") as f:
    content = f.read()

ck("start", {"target": TARGET, "keys": len(T), "plurals": len(PLURALS)})

applied = []
skipped_new = []

# --- 1. Replace existing string keys via regex ---
for i, (key, val) in enumerate(T.items()):
    if key in NEW_KEYS:
        continue
    # pattern matches <string name="key" ...>...</string> (any attrs, multiline content)
    pat = re.compile(r'(<string name="' + re.escape(key) + r'"[^>]*>).*?(</string>)', re.DOTALL)
    if not pat.search(content):
        skipped_new.append(key)  # not present -> will treat as new insert later
        continue
    repl = r'\g<1>' + esc(val) + r'\g<2>'
    content, n = pat.subn(repl, content, count=1)
    applied.append(key)
    if (i + 1) % 10 == 0:
        ck("progress", {"applied_so_far": len(applied)})

# --- 2. Replace plurals (existing -> replace whole block) ---
plurals_done = 0
for pkey, items in PLURALS.items():
    inner = ""
    for qty, txt in items.items():
        inner += f'        <item quantity="{qty}">{txt}</item>\n'
    block = f'<plurals name="{pkey}">\n{inner}    </plurals>'
    pat = re.compile(r'<plurals name="' + re.escape(pkey) + r'">.*?</plurals>', re.DOTALL)
    if pat.search(content):
        content = pat.sub(lambda m: block, content, count=1)
        plurals_done += 1
    else:
        skipped_new.append("PLURAL:" + pkey)

ck("strings_plurals_done", {"applied": len(applied), "plurals_done": plurals_done, "skipped": skipped_new})

# --- 3. Insert new keys (paywall_monthly_note + any string not found) + missing plurals via rfind ---
new_blocks = ""
for key in NEW_KEYS:
    cnt = subprocess.run(['grep','-c',f'name="{key}"',TARGET], capture_output=True, text=True).stdout.strip()
    if int(cnt or '0') > 0 or ('<string name="'+key+'"') in content:
        continue
    new_blocks += f'    <string name="{key}">{T[key]}</string>\n'

# any string that was missing (skipped_new without PLURAL prefix) -> insert
for key in list(skipped_new):
    if key.startswith("PLURAL:"):
        continue
    if ('<string name="'+key+'"') in content:
        continue
    new_blocks += f'    <string name="{key}">{T[key]}</string>\n'

# missing plurals -> insert
for sk in skipped_new:
    if sk.startswith("PLURAL:"):
        pkey = sk.split(":",1)[1]
        items = PLURALS[pkey]
        inner = "".join(f'        <item quantity="{q}">{t}</item>\n' for q,t in items.items())
        new_blocks += f'    <plurals name="{pkey}">\n{inner}    </plurals>\n'

inserted_new = []
if new_blocks:
    idx = content.rfind('</resources>')
    if idx == -1:
        raise RuntimeError(f"{TARGET}: kein </resources> gefunden")
    content = content[:idx] + new_blocks + content[idx:]
    inserted_new = [b for b in NEW_KEYS]

with open(TARGET, "w", encoding="utf-8", newline="\n") as f:
    f.write(content)

ck("written", {"applied": len(applied), "plurals_done": plurals_done, "inserted_new": inserted_new})
print("APPLIED:", len(applied))
print("PLURALS_DONE:", plurals_done)
print("INSERTED_NEW:", inserted_new)
print("SKIPPED_NEW_INSERTED:", [s for s in skipped_new])
